CREATE OR REPLACE FUNCTION public.guard_exchange_authorization() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.status <> 'pending' OR NEW.proposer_id=NEW.receiver_id OR (auth.role() <> 'service_role' AND NEW.proposer_id IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Invalid exchange proposal'; END IF; ELSE IF NEW.proposer_id IS DISTINCT FROM OLD.proposer_id OR NEW.receiver_id IS DISTINCT FROM OLD.receiver_id OR NEW.offered_product_id IS DISTINCT FROM OLD.offered_product_id OR NEW.requested_product_id IS DISTINCT FROM OLD.requested_product_id THEN RAISE EXCEPTION 'Exchange identity is immutable'; END IF; IF NEW.status IS DISTINCT FROM OLD.status THEN IF OLD.status <> 'pending' OR NOT ((auth.uid()=OLD.receiver_id AND NEW.status IN ('accepted','rejected')) OR (auth.uid()=OLD.proposer_id AND NEW.status='cancelled')) THEN RAISE EXCEPTION 'Unauthorized exchange transition'; END IF; END IF; END IF; IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=NEW.offered_product_id AND seller_id=NEW.proposer_id AND status='published' AND is_tradable) OR NOT EXISTS(SELECT 1 FROM public.products WHERE id=NEW.requested_product_id AND seller_id=NEW.receiver_id AND status='published' AND is_tradable) THEN RAISE EXCEPTION 'Invalid exchange products'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.guard_exchange_authorization() FROM PUBLIC,anon,authenticated; CREATE TRIGGER guard_exchange_authorization_trg BEFORE INSERT OR UPDATE ON public.exchanges FOR EACH ROW EXECUTE FUNCTION public.guard_exchange_authorization(); CREATE OR REPLACE FUNCTION public.guard_exchange_item_authorization() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.exchanges e JOIN public.products p ON p.id=NEW.product_id WHERE e.id=NEW.exchange_id AND e.status='pending' AND e.proposer_id=auth.uid() AND p.status='published' AND p.is_tradable AND ((NEW.side='offered' AND p.seller_id=e.proposer_id) OR (NEW.side='requested' AND p.seller_id=e.receiver_id AND p.id=e.requested_product_id))) THEN RAISE EXCEPTION 'Invalid exchange item'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.guard_exchange_item_authorization() FROM PUBLIC,anon,authenticated; CREATE TRIGGER guard_exchange_item_authorization_trg BEFORE INSERT OR UPDATE ON public.exchange_items FOR EACH ROW EXECUTE FUNCTION public.guard_exchange_item_authorization();